// Normaliza payload — GHL puede mandar como query, body, o body string
// IMPORTANTE: cuando viene de GHL Workflow Webhook Action, los Custom Data fields
// llegan EN body.customData.*, mientras que contact_id, first_name, etc.
// llegan al ROOT de body.*. Mergeamos ambos.
const raw = $input.first().json;
let root = {};
if (raw && typeof raw.body === 'object' && Object.keys(raw.body).length) root = raw.body;
else if (raw && typeof raw.query === 'object' && Object.keys(raw.query).length) root = raw.query;
else if (typeof raw === 'object') root = raw;

// Merge: root keys ganan, pero customData fills appointment_id/start_time/end_time si faltan en root
const customData = (root.customData && typeof root.customData === 'object') ? root.customData : {};
const src = Object.assign({}, customData, root);
// Si appointment_id/start_time aún no están en src, tomarlos de customData explícitamente
if (!src.appointment_id && customData.appointment_id) src.appointment_id = customData.appointment_id;
if (!src.start_time && customData.start_time) src.start_time = customData.start_time;
if (!src.end_time && customData.end_time) src.end_time = customData.end_time;
// También revisar calendar.appointmentId como fallback
if (!src.appointment_id && root.calendar && root.calendar.appointmentId) src.appointment_id = root.calendar.appointmentId;

// Parser de fecha GHL: "Thursday, April 30, 2026 3:30 PM" → ISO con offset Cancún (-05:00)
const MONTHS = {January:0,February:1,March:2,April:3,May:4,June:5,July:6,August:7,September:8,October:9,November:10,December:11};
function parseGHLDate(s) {
  if (!s || typeof s !== 'string') return null;
  const m = s.match(/\w+,\s+(\w+)\s+(\d+),\s+(\d+)\s+(\d+):(\d+)\s*(AM|PM)/i);
  if (!m) return null;
  let [, mon, day, year, h, mi, ap] = m;
  let H = parseInt(h, 10) % 12;
  if (/PM/i.test(ap)) H += 12;
  const mon_n = MONTHS[mon];
  if (mon_n === undefined) return null;
  const pad = (n) => String(n).padStart(2, '0');
  return `${year}-${pad(mon_n + 1)}-${pad(day)}T${pad(H)}:${pad(mi)}:00-05:00`;
}

function normalizePhone(p) {
  if (!p) return null;
  const digits = String(p).replace(/\D/g, '');
  if (!digits) return null;
  if (digits.startsWith('52')) return digits;
  if (digits.length === 10) return '52' + digits;
  return digits;
}

const startISO = parseGHLDate(src.start_time);
const endISO = parseGHLDate(src.end_time);
const startDate = startISO ? startISO.slice(0, 10) : null;
const startTimeOnly = startISO ? startISO.slice(11, 19) : null;
const durationMin = (startISO && endISO) ? Math.round((new Date(endISO) - new Date(startISO)) / 60000) : null;

function shortCode() {
  const ts = Date.now().toString(36).toUpperCase().slice(-5);
  const rnd = Math.random().toString(36).toUpperCase().slice(2, 5);
  return `EX-${ts}${rnd}`;
}

const nombre = [src.first_name, src.last_name].filter(Boolean).join(' ').trim() || null;

return [{
  json: {
    ghl_appointment_id: src.appointment_id || null,
    ghl_contact_id: src.contact_id || null,
    cliente_email: src.email || null,
    cliente_telefono: normalizePhone(src.phone),
    cliente_nombre: nombre,
    fecha_agendada: startDate,
    hora_agendada: startTimeOnly,
    duracion_total_min: durationMin,
    start_iso: startISO,
    end_iso: endISO,
    booking_code: shortCode(),
    raw_start_time: src.start_time,
    raw_end_time: src.end_time
  }
}];

// Merge appointment data (from Normalize) with GHL custom fields
const appt = $('Normalize payload').item.json;
const ghlResp = $input.first().json;

// Extract custom fields from GHL contact response
const cfs = ghlResp?.contact?.customFields || ghlResp?.customFields || [];
const cfMap = {};
for (const cf of cfs) {
  if (cf.id && cf.value !== undefined && cf.value !== null && cf.value !== '') {
    cfMap[cf.id] = cf.value;
  }
}

// Custom field IDs → readable keys
const CF_IDS = {
  'ETSBOfoZqy1ng2RFBPzm': 'servicio_elegido',
  'JgsK2j4h1p6Gf7pw0WDS': 'lead_ref',
  'vx52ah4vkjC7OENE0lWU': 'fbclid',
  'xgBoQXRSmURvYvhaxEzN': 'gclid',
  '37CfTVmnM6SUFq6XUnHh': 'utm_source',
  'NZPrbivrqIQFQx40cSsD': 'utm_medium',
  'Kc5n7iZqisG3PBKhufQd': 'utm_campaign',
  'vVUbV7gxxxTpfefQyCLG': 'zona',
  'Ufj0CBEGwYouDqvcwPXD': 'preferencia_sexo',
  'E3eEAnNb1rXfbh0Up3EE': 'valor_ticket_mxn'
};

const extracted = {};
for (const [id, key] of Object.entries(CF_IDS)) {
  extracted[key] = cfMap[id] || null;
}

// Build servicios jsonb array from the comma-separated string
let servicios = [];
if (extracted.servicio_elegido) {
  servicios = extracted.servicio_elegido
    .split(',')
    .map(s => s.trim())
    .filter(Boolean)
    .map(s => ({ slug: s }));
}

// Build attribution object
const atribucion = {};
if (extracted.fbclid) atribucion.fbclid = extracted.fbclid;
if (extracted.gclid) atribucion.gclid = extracted.gclid;
if (extracted.utm_source) atribucion.utm_source = extracted.utm_source;
if (extracted.utm_medium) atribucion.utm_medium = extracted.utm_medium;
if (extracted.utm_campaign) atribucion.utm_campaign = extracted.utm_campaign;

return [{
  json: {
    // Appointment fields
    ...appt,
    // Enriched fields from GHL custom fields
    servicios: servicios,
    lead_ref: extracted.lead_ref,
    zona_colonia: extracted.zona,
    preferencia_sexo: (extracted.preferencia_sexo || 'I').toUpperCase().charAt(0),
    valor_ticket_mxn: extracted.valor_ticket_mxn ? parseFloat(extracted.valor_ticket_mxn) : null,
    atribucion: Object.keys(atribucion).length > 0 ? atribucion : null,
    // Flag: did we get GHL data?
    ghl_enriched: cfs.length > 0
  }
}];
